draw(Circle((r1,r1),r1));
label("$A$",(sqrt(3),0),SE);
label("$B$",(0,1),NW);
label("$O$",(r1,r1),ESE);
label("$C$",(0,r1),W);
label("$D$",(0,0),SW);
label("$E$",(r1,0),S);
label("$F$",(r1,r1)+r1*dir(60),dir(60));
draw(rightanglemark((0,1),origin,(1,0),3));
draw((r1,r1)+r1*dir(60)--(r1,r1)--(0,r1));
draw((r1,0)--(r1,r1)--(0,1));
draw((r1,r1)--(0,1));
[/asy]

